-- Inclui mudança de propriedade de diligências no escopo privado do histórico.
CREATE OR REPLACE FUNCTION assistente_privado.escopo() RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$
 SELECT md5(coalesce((SELECT string_agg(role::text,',' ORDER BY role::text) FROM public.user_roles WHERE user_id=auth.uid()),'')||'|'||coalesce((SELECT string_agg(modulo::text||':'||acao::text||':'||permitido::text,',' ORDER BY modulo,acao) FROM public.user_permissions WHERE user_id=auth.uid()),'')||'|'||coalesce((SELECT string_agg(id::text,',' ORDER BY id) FROM public.processos WHERE public.usuario_ve_processo(auth.uid(),id)),'')||'|'||coalesce((SELECT string_agg(id::text,',' ORDER BY id) FROM public.clientes WHERE public.usuario_ve_cliente(auth.uid(),id)),'')||'|'||coalesce((SELECT string_agg(id::text,',' ORDER BY id) FROM public.controladoria_itens WHERE responsavel_id=auth.uid() OR executor_id=auth.uid() OR revisor_id=auth.uid()),'')||'|'||coalesce((SELECT string_agg(id::text,',' ORDER BY id) FROM public.diligencias WHERE criado_por=auth.uid()),'')||'|'||coalesce((SELECT ativo::text||':'||tipo_portal FROM public.profiles WHERE id=auth.uid()),'')) WHERE auth.uid() IS NOT NULL AND public.is_interno_ativo(auth.uid())
$$;
